#include <vector>
#include <cstddef>
#include <cmath>
#include <omp.h>

double productWithInverses(std::vector<double> const& x) {
    const std::size_t n = x.size();
    if (n == 0) return 1.0;

    // Use log-sum to make the result robust to OpenMP reduction order.
    // product = exp( sum_i log(|term_i|) ) * sign(product)
    // where term_i = x[i] for even i, and 1/x[i] for odd i.
    double logsum = 0.0;
    int sign_prod = 1;

    #pragma omp parallel
    {
        double local_logsum = 0.0;
        int local_sign = 1;

        #pragma omp for nowait
        for (std::size_t i = 0; i < n; ++i) {
            const double xi = x[i];
            // term = xi (even), or 1/xi (odd) => abs(term)=abs(xi) or 1/abs(xi)
            const double ax = std::fabs(xi);

            // log(abs(term))
            if ((i & 1u) == 0u) {
                local_logsum += std::log(ax);
            } else {
                local_logsum -= std::log(ax);
            }

            // sign(term): sign(xi) for even, sign(1/xi)==sign(xi) for odd
            if (std::signbit(xi)) local_sign = -local_sign;
        }

        #pragma omp atomic
        logsum += local_logsum;

        #pragma omp critical
        {
            sign_prod *= local_sign;
        }
    }

    return sign_prod * std::exp(logsum);
}
